<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>BizzSmart Admin — Demo requests</title><style>:root{--navy:#08142f;--blue:#586ff2;--muted:#768196;--line:#e8ebf2}*{box-sizing:border-box}body{margin:0;background:#f6f8fc;color:#17213b;font-family:Arial,sans-serif}.top{background:var(--navy);color:#fff;padding:19px 0}.wrap{width:min(1120px,calc(100% - 36px));margin:auto}.top-in{display:flex;align-items:center;justify-content:space-between}.brand{font-size:20px;font-weight:800}.brand span{color:#6c80ff}.top small{color:#aab6ce;font-size:11px}.logout{border:1px solid #44537a;background:transparent;color:#fff;border-radius:7px;padding:8px 12px;font-size:11px;cursor:pointer}.hero{padding:38px 0 25px;display:flex;justify-content:space-between;align-items:end}.eyebrow{color:#6475ed;letter-spacing:2px;font-size:10px;font-weight:700}.hero h1{margin:8px 0 0;font-size:30px}.stats{display:flex;gap:12px}.stat{background:#fff;border:1px solid var(--line);border-radius:10px;padding:15px 22px;min-width:115px}.stat small{display:block;color:var(--muted);font-size:10px}.stat strong{font-size:23px;display:block;margin-top:4px}.toolbar{background:#fff;border:1px solid var(--line);padding:14px;border-radius:10px;display:flex;justify-content:space-between;align-items:center;margin-bottom:14px}.search{display:flex;gap:8px}.search input{width:280px;border:1px solid #dde2ec;border-radius:7px;padding:10px;font-size:12px}.search button{border:0;background:var(--blue);color:#fff;border-radius:7px;padding:0 15px;font-weight:700;font-size:11px}.hint{color:var(--muted);font-size:11px}.table-wrap{background:#fff;border:1px solid var(--line);border-radius:10px;overflow:auto}table{border-collapse:collapse;width:100%;min-width:850px}th{text-align:left;background:#fafbfe;color:#8791a3;font-size:10px;letter-spacing:.5px;text-transform:uppercase;padding:14px;border-bottom:1px solid var(--line)}td{padding:15px 14px;border-bottom:1px solid #f0f2f6;font-size:12px;vertical-align:top}td b{font-size:13px}td small{display:block;color:var(--muted);font-size:10px;margin-top:4px}.badge{display:inline-block;background:#e7f8f2;color:#188161;border-radius:20px;padding:5px 9px;font-size:9px}.delete{border:0;background:#fff0ed;color:#bf594b;border-radius:5px;padding:6px 8px;font-size:10px;cursor:pointer}.empty{text-align:center;color:var(--muted);padding:55px}.success{background:#e7f8f2;color:#147653;padding:11px;border-radius:7px;font-size:12px;margin-bottom:14px}.pagination{padding:15px}.pagination nav{display:flex;justify-content:center}.pagination svg{width:18px}.pagination a,.pagination span{margin:0 3px;padding:6px 9px;border:1px solid var(--line);border-radius:5px;font-size:11px;text-decoration:none;color:#5363db}.pagination span[aria-current]{background:var(--blue);color:#fff}@media(max-width:700px){.hero{display:block}.stats{margin-top:22px}.toolbar{display:block}.search{margin-bottom:10px}.search input{width:calc(100% - 70px)}} </style></head><body><header class="top"><div class="wrap top-in"><div><div class="brand">Bizz<span>Smart</span></div><small>Admin console</small></div><form method="POST" action="{{ route('admin.logout') }}">@csrf<button class="logout" type="submit">Sign out</button></form></div></header><main class="wrap"><section class="hero"><div><div class="eyebrow">LEAD MANAGEMENT</div><h1>Demo requests</h1></div><div class="stats"><div class="stat"><small>Total requests</small><strong>{{ $totalRequests }}</strong></div><div class="stat"><small>Today</small><strong>{{ $todayRequests }}</strong></div></div></section>@if(session('success'))<div class="success">✓ {{ session('success') }}</div>@endif<div class="toolbar"><form class="search" method="GET"><input name="search" value="{{ request('search') }}" placeholder="Search name, company, phone or email"><button type="submit">Search</button></form><span class="hint">Newest requests first</span></div><div class="table-wrap"><table><thead><tr><th>Contact</th><th>Company</th><th>Business</th><th>Team</th><th>Message</th><th>Received</th><th></th></tr></thead><tbody>@forelse($requests as $demo)<tr><td><b>{{ $demo->name }}</b><small>{{ $demo->phone }}</small><small>{{ $demo->email ?: 'No email provided' }}</small></td><td>{{ $demo->company }}</td><td><span class="badge">{{ $demo->business_type ?: 'Not specified' }}</span></td><td>{{ $demo->team_size ?: '—' }}</td><td>{{ $demo->message ?: '—' }}</td><td>{{ $demo->created_at->format('d M Y, h:i A') }}</td><td><form method="POST" action="{{ route('admin.requests.destroy', $demo) }}" onsubmit="return confirm('Delete this request?')">@csrf @method('DELETE')<button class="delete" type="submit">Delete</button></form></td></tr>@empty<tr><td class="empty" colspan="7">No demo requests found.</td></tr>@endforelse</tbody></table></div><div class="pagination">{{ $requests->links() }}</div></main></body></html>
